<script setup>import { Head } from '@inertiajs/vue3'; import AppLayout from '../Layouts/AppLayout.vue'; import ResourceCrud from './Partials/ResourceCrud.vue'; defineProps({records:Object,institutions:Array}); const statuses=['Activa','En preparación','Presentada','Adjudicada','Perdida','Cancelada'].map(value=>({value,label:value})); const fields=[{key:'reference',label:'Proceso'},{key:'title',label:'Título'},{key:'institution_id',label:'Institución',type:'institution'},{key:'purchase_type',label:'Tipo'},{key:'estimated_amount',label:'Monto',type:'number'},{key:'published_at',label:'Publicación',type:'date'},{key:'closing_date',label:'Cierre',type:'date'},{key:'status',label:'Estado',type:'select',default:'Activa',options:statuses},{key:'offer_submitted',label:'Oferta presentada',type:'checkbox'},{key:'result',label:'Resultado'},{key:'observations',label:'Observaciones',type:'textarea'}];</script><template><Head title="Licitaciones"/><AppLayout><div class="module-toolbar"><button class="export pdf" @click="window.location.assign('/licitaciones/export/pdf')">PDF</button><button class="export excel" @click="window.location.assign('/licitaciones/export/xlsx')">XLSX</button></div><ResourceCrud title="Licitaciones" :records="records" :institutions="institutions" :fields="fields" create-url="/licitaciones" update-url="/licitaciones/:id" delete-url="/licitaciones/:id"/></AppLayout></template>
